record.field:
# Find all pending (not yet deducted) missing breaks for selected employees
missing_breaks = env['hr.missing.break'].search([
    ('employee_id', 'in', records.ids),
    ('deducted', '=', False),
])
if missing_breaks:
    action = missing_breaks.with_context(active_model='hr.employee').action_deduct_missing_break()
else:
    action = {
        'type': 'ir.actions.client',
        'tag': 'display_notification',
        'params': {
            'title': 'Nothing to Deduct',
            'message': 'No pending missing breaks found for the selected employees.',
            'type': 'warning',
            'sticky': False,
        },
    }
